begin
 for c in select value from jsonb_array_elements(fixture->'cases') loop
  select coalesce(jsonb_agg(jsonb_build_object('spec',spec_id,'instant',fire_at,'signature',signature) order by fire_at,spec_id),'[]') into actual
   from taskfold_private.reminder_events(c->'task',c->>'zone');
  if jsonb_array_length(actual)<>jsonb_array_length(c->'events') then raise exception 'Projection count mismatch: %',c->>'name'; end if;
  for e in select value from jsonb_array_elements(c->'events') loop
   if not exists(select 1 from jsonb_array_elements(actual) a where a->>'spec'=e->>'spec' and (a->>'instant')::timestamptz=(e->>'instant')::timestamptz and a->>'signature'=e->>'signature') then raise exception 'Projection mismatch: %, got %',c->>'name',actual; end if;
  end loop;
 end loop;
end $$;
