do $$ declare device uuid:='f6001000-0000-4000-8000-000000000021'; batch jsonb; job jsonb; payload jsonb; old_lease uuid; jobkey text; n int; begin
 if public.taskfold_reconcile_reminder_jobs(device)->>'queued'<>'1' then raise exception 'Expected one private owner occurrence'; end if;
 if public.taskfold_reconcile_reminder_jobs(device)->>'queued'<>'0' then raise exception 'Reconcile duplicated logical event'; end if;
 batch:=public.taskfold_claim_reminder_jobs(device,25); if jsonb_array_length(batch)<>1 then raise exception 'Claim failed'; end if; job:=batch->0; jobkey:=job->>'id'; old_lease:=(job->>'lease')::uuid;
 if (job-array['id','device','account','task','spec','signature','fire_at','lease','attempt'])<>'{}'::jsonb then raise exception 'Claim exposed provider payload'; end if;
 if public.taskfold_claim_reminder_jobs(device,25)<>'[]'::jsonb then raise exception 'Concurrent lease could be claimed again'; end if;
 if public.taskfold_prepare_reminder_job(jobkey,gen_random_uuid()) is not null or public.taskfold_finish_reminder_job(jobkey,gen_random_uuid(),'accepted') then raise exception 'Wrong lease accepted'; end if;
 payload:=public.taskfold_prepare_reminder_job(jobkey,old_lease);
 if payload is null or payload->'content'->'info'->>'signature'<>job->>'signature' or payload->'content'->>'title'<>'Never stored in the job' or payload->'binding'->>'token'<>'aa11' then raise exception 'Dispatch did not revalidate current payload'; end if;
 if (select to_jsonb(j) from taskfold_private.reminder_jobs j where j.id=jobkey) ?| array['title','description','binding','token','secret'] then raise exception 'Queue retained private content'; end if;
 if not public.taskfold_finish_reminder_job(jobkey,old_lease,'transient') then raise exception 'Transient outcome rejected'; end if;
 if public.taskfold_claim_reminder_jobs(device,25)<>'[]'::jsonb then raise exception 'Retry bypassed backoff'; end if;
 update taskfold_private.reminder_jobs set next_attempt=now()-interval '1 second' where reminder_jobs.id=jobkey;
 job:=public.taskfold_claim_reminder_jobs(device,25)->0;
 if job->>'attempt'<>'2' or (job->>'lease')::uuid=old_lease or public.taskfold_finish_reminder_job(jobkey,old_lease,'accepted') then raise exception 'Retry did not fence old receipt'; end if;
 update taskfold_private.reminder_jobs set lease_until=now()-interval '1 second',next_attempt=now()-interval '1 second' where reminder_jobs.id=jobkey;
 old_lease:=(job->>'lease')::uuid; job:=public.taskfold_claim_reminder_jobs(device,25)->0;
 if job->>'attempt'<>'3' or public.taskfold_finish_reminder_job(jobkey,old_lease,'accepted') then raise exception 'Restart lease not fenced'; end if;
 if not public.taskfold_finish_reminder_job(jobkey,(job->>'lease')::uuid,'accepted') then raise exception 'Accepted delivery not retained'; end if;
 if public.taskfold_reconcile_reminder_jobs(device)->>'queued'<>'0' or public.taskfold_claim_reminder_jobs(device,25)<>'[]'::jsonb then raise exception 'Accepted event resent'; end if;
 if public.taskfold_prepare_reminder_job(jobkey,(job->>'lease')::uuid) is not null then raise exception 'Sent event prepared again'; end if;
 if public.taskfold_reconcile_reminder_jobs('f6001000-0000-4000-8000-000000000022')->>'queued'<>'1' then raise exception 'Member-owned accessible task not queued'; end if;
end $$;
