do $$ declare device uuid:='f6001000-0000-4000-8000-000000000021'; job jsonb; begin
 -- Actual task mutation triggers immediately cancel a lease before dispatch/acknowledgement.
 update public.tasks set reminder_specs=jsonb_set(reminder_specs,'{0,at}',to_jsonb(to_char(timezone('UTC',now()-interval '2 minutes'),'YYYY-MM-DD"T"HH24:MI:SS"Z"'))) where id='f6001000-0000-4000-8000-000000000041';
 perform public.taskfold_reconcile_reminder_jobs(device); job:=public.taskfold_claim_reminder_jobs(device,1)->0;
 update public.tasks set completed=true where id='f6001000-0000-4000-8000-000000000041';
 if public.taskfold_prepare_reminder_job(job->>'id',(job->>'lease')::uuid) is not null or public.taskfold_finish_reminder_job(job->>'id',(job->>'lease')::uuid,'accepted') then raise exception 'Completed occurrence could dispatch'; end if;
 update public.tasks set completed=false where id='f6001000-0000-4000-8000-000000000041';
 if public.taskfold_reconcile_reminder_jobs(device)->>'queued'<>'1' then raise exception 'Reopen cycle did not create new signature'; end if;
 job:=public.taskfold_claim_reminder_jobs(device,1)->0;
 -- Permission/revision changes invalidate held leases, even when the task itself is unchanged.
 update taskfold_private.reminder_devices set revision=revision+1,binding=jsonb_set(binding,'{enabled}','false') where id=device;
 if public.taskfold_prepare_reminder_job(job->>'id',(job->>'lease')::uuid) is not null then raise exception 'Disabled device retained prepared payload'; end if;
 update taskfold_private.reminder_devices set revision=revision+1,binding=jsonb_set(binding,'{enabled}','true') where id=device;
