 if public.taskfold_reconcile_reminder_jobs(device)->>'queued'<>'0' then raise exception 'Opt-in resurrected old cancelled alert'; end if;
 update public.tasks set reminder_specs=jsonb_set(reminder_specs,'{0,at}',to_jsonb(to_char(timezone('UTC',now()-interval '3 minutes'),'YYYY-MM-DD"T"HH24:MI:SS"Z"'))) where id='f6001000-0000-4000-8000-000000000041';
 perform public.taskfold_reconcile_reminder_jobs(device);
 update taskfold_private.reminder_jobs set attempts=7 where device_id=device and state='pending';
 job:=public.taskfold_claim_reminder_jobs(device,1)->0;
 if job->>'attempt'<>'8' or not public.taskfold_finish_reminder_job(job->>'id',(job->>'lease')::uuid,'transient') then raise exception 'Last retry failed'; end if;
 if not exists(select 1 from taskfold_private.reminder_jobs where id=job->>'id' and state='failed') then raise exception 'Exhausted retry stayed pending'; end if;
 update public.tasks set reminder_specs=jsonb_set(reminder_specs,'{0,at}',to_jsonb(to_char(timezone('UTC',now()-interval '4 minutes'),'YYYY-MM-DD"T"HH24:MI:SS"Z"'))) where id='f6001000-0000-4000-8000-000000000041';
 perform public.taskfold_reconcile_reminder_jobs(device); job:=public.taskfold_claim_reminder_jobs(device,1)->0;
 if not public.taskfold_finish_reminder_job(job->>'id',(job->>'lease')::uuid,'invalid_token') then raise exception 'Invalid token not retired'; end if;
 if exists(select 1 from taskfold_private.reminder_devices where id=device and binding is not null) then raise exception 'Invalid address remained active'; end if;
 update taskfold_private.reminder_devices set expires_at=now()-interval '1 second' where id='f6001000-0000-4000-8000-000000000022';
 if public.taskfold_maintain_reminder_queue(1000)->>'retired'<>'1' then raise exception 'Expired registry quota not retired'; end if;
 if exists(select 1 from taskfold_private.reminder_devices where id='f6001000-0000-4000-8000-000000000022' and binding is not null) then raise exception 'Expired address retained'; end if;
end $$;
reset role;
do $$ begin
 if has_function_privilege('anon','public.taskfold_prepare_reminder_job(text,uuid)','execute') or has_function_privilege('authenticated','public.taskfold_reconcile_reminder_jobs(uuid)','execute') or has_table_privilege('authenticated','taskfold_private.reminder_jobs','select') or has_function_privilege('authenticated','taskfold_private.reminder_session_live(uuid,uuid)','execute') or has_table_privilege('service_role','auth.sessions','select') then raise exception 'Queue/Auth privilege boundary incorrect'; end if;
